async function traslado(a, b) {            // mover 1 bulto del depósito a al depósito b
  for (;;) {
    const c = await pool.connect();
    try {
      await c.query('begin');
      if (ordenado)                         // la defensa: bloquear SIEMPRE en el mismo orden
        await c.query('select id from dep where id in ($1, $2) order by id for update', [a, b]);
      await c.query('update dep set bultos = bultos - 1 where id = $1', [a]);
      await new Promise(r => setTimeout(r, 5));   // trabajo entre las dos escrituras
      await c.query('update dep set bultos = bultos + 1 where id = $1', [b]);
      await c.query('commit'); return;
    } catch (e) {
      await c.query('rollback').catch(() => {});
      if (e.code === '40P01') continue;     // deadlock: se repite la transacción entera
      throw e;
    } finally { c.release(); }
  }
}

create function reclamar_con_candado(u text) returns boolean language plpgsql as $$
begin
  perform pg_advisory_xact_lock(hashtext('trivia:' || u));   -- un candado por usuario
  if (select count(*) from cobradas where usuario = u) >= 2 then return false; end if;
  insert into cobradas (usuario) values (u);
  return true;
end $$;
